const { chromium } = require('playwright');
const SHOTS = [
  ['map', 'quickSetup();ST.role="visitor";V.map()'], ['poi_barC', 'quickSetup();V.map();V.poiSheet("barC")'], ['poi_scene', 'quickSetup();V.map();V.poiSheet("scene")'], ['poi_partner', 'quickSetup();V.map();V.poiSheet("partner")'],
  ['friend_lea', 'quickSetup();V.map();V.friendSheet("lea")'], ['friend_sami', 'quickSetup();V.map();V.friendSheet("sami")'], ['route', 'quickSetup();V.map();V.goTo(POIS.find(p=>p.id==="barE").at,"Bar Est","Q")'],
  ['report', 'quickSetup();V.map();V.report()'], ['reportDetail', 'quickSetup();V.map();V.reportDetail("medical")'], ['rdv', 'quickSetup();V.map();V.rdvSheet(null)'], ['share', 'quickSetup();V.map();V.shareSettings()'],
  ['layers', 'quickSetup();V.map();V.layers()'], ['crowd', 'quickSetup();showCrowd=true;V.map()'], ['friends', 'quickSetup();V.friendsTab()'], ['chatList', 'quickSetup();V.chatList()'], ['chat', 'quickSetup();V.chat("lea")'],
  ['notifs', 'quickSetup();V.notifs()'], ['search', 'quickSetup();V.search()'], ['settings', 'quickSetup();V.settings()'], ['recap', 'quickSetup();V.recap()'], ['replay', 'quickSetup();V.replay()'],
  ['offline', 'quickSetup();ST.offline=true;V.map()'], ['guest', 'resetDemo();ST.account="guest";V.map()'],
  ['staffMap', 'ST.role="staff";S.map()'], ['staffAlerts', 'ST.role="staff";S.alerts()'], ['staffAlert', 'ST.role="staff";S.map();S.alert(9001)'], ['staffTeam', 'S.team()'], ['bar', 'ST.role="bar";S.bar()'], ['find', 'ST.role="visitor";quickSetup();V.findFriend("lea")'], ['lock', 'quickSetup();V.lock()'], ['reportHarass', 'quickSetup();V.map();V.reportDetail("harass")'], ['avQuick', 'quickSetup();V.avatarQuick()'], ['avEditor', 'quickSetup();V.avatarEditor(null)'], ['wallet', 'quickSetup();V.map();V.wallet()'], ['family', 'quickSetup();applyTemplate("park");V.map();V.family()'], ['parkMap', 'quickSetup();applyTemplate("park");ST.flags.push("familyOn");V.map()'], ['concertEvent', 'quickSetup();applyTemplate("concert");V.map();V.eventSheet()'], ['desertOffline', 'quickSetup();applyTemplate("desert");ST.offline=true;V.map()'], ['clubMap', 'quickSetup();applyTemplate("club");ST.offline=false;V.map()'], ['clubBar', 'quickSetup();setVenue("bisous");V.map();V.poiSheet("barP")'], ['selvaMap', 'quickSetup();setVenue("selva");V.map()'], ['darkMap', 'quickSetup();setVenue("bdf");ST.theme="dark";V.map()'], ['darkSettings', 'quickSetup();ST.theme="dark";V.settings()'], ['enMap', 'quickSetup();ST.theme="light";ST.lang="en";V.map()'], ['enFriend', 'quickSetup();V.friendSheet("lea")']
];
(async () => { const b = await chromium.launch(); const p = await b.newPage({ viewport: { width: 1360, height: 900 } });
  await p.goto('http://127.0.0.1:8090/local.html'); await p.waitForTimeout(600);
  for (const [n, s] of SHOTS) { await p.evaluate(`(()=>{document.querySelector('#dash')&&closeDash();if(!/setVenue|applyTemplate|theme|lang|enFriend/.test(${JSON.stringify(n + s)})){setVenue('bdf');ST.theme='light';ST.lang='fr';ST.offline=false;ST.flags=['wallet'];}${s}})()`); await p.waitForTimeout(900); await p.locator('#screen').screenshot({ path: `gal3/${n}.png` }); }
  for (const v of ['report', 'templates', 'global', 'prep', 'team', 'alerts', 'replay', 'compare', 'prog', 'bars', 'comm', 'beacons', 'data']) { await p.evaluate(`openDash("${v}")`); await p.waitForTimeout(1000); await p.screenshot({ path: `gal3/dash_${v}.png`, fullPage: false }); }
  await p.evaluate('setVenue("bdf");ST.lang="fr";D.crisis=true;openDash("alerts")'); await p.waitForTimeout(900); await p.screenshot({ path: 'gal3/dash_crisis.png' }); await p.evaluate('D.crisis=false;D.ev="club";openDash("club")'); await p.waitForTimeout(900); await p.screenshot({ path: 'gal3/dash_club.png' }); await p.evaluate('D.ev="bdf"');
  await b.close(); })();
